INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('e2040000-0000-4000-8000-000000000001', 'e2030000-0000-4000-8000-000000000001', 1, 'TEXT', 'Với trắc nghiệm một đáp án, đọc câu hỏi và ba đáp án trước, rồi tìm đoạn liên quan nhờ từ khóa. Đáp án đúng thường dùng từ đồng nghĩa, không lặp lại đúng chữ trong bài. Loại đáp án sai: nói ngược lại, thêm thông tin không có hoặc chỉ đúng một phần.');
