INSERT INTO content_assets (id, asset_type, text_content, validation_status) VALUES ('e2050000-0000-4000-8000-000000000002', 'PASSAGE', 'The city park was built in 1990. It has a large lake, and many people visit it at weekends. They come to run, to cycle or simply to relax. These visits have increased since the council planted trees along the paths. This has made the park cooler in summer, which is why families now stay longer.', 'VALID');
