INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('e2040000-0000-4000-8000-000000000004', 'e2030000-0000-4000-8000-000000000002', 1, 'TEXT', 'Đại từ như it, they, these, this thay cho danh từ hoặc cả ý ở câu trước. Khi gặp một từ thay thế, hãy đọc lại câu trước nó và hỏi: nó nói về cái gì? "They" thường là số nhiều gần nhất, "this" có thể là cả hành động ở câu trước.');
