INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('e2040000-0000-4000-8000-000000000013', 'e2030000-0000-4000-8000-000000000005', 1, 'TEXT', 'Mỗi đoạn có một nhiệm vụ: giới thiệu vấn đề, đưa lý do, nêu ví dụ hoặc kết luận. Cụm "for example" báo ví dụ, "therefore" báo kết luận, "the first ... the second ..." báo danh sách lý do. Hỏi: đoạn này làm gì cho cả bài, không chỉ nói gì.');
