INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('e2040000-0000-4000-8000-000000000016', 'e2030000-0000-4000-8000-000000000006', 1, 'TEXT', 'Bài Reading có 60 phút cho ba bài, tức khoảng 20 phút một bài. Dành 2–3 phút đọc lướt, rồi làm câu hỏi theo thứ tự. Nếu một câu mất quá hai phút, đánh dấu và đi tiếp. Dành 2 phút cuối kiểm tra lại các câu đã bỏ. Đừng để trống câu nào, hãy đoán nếu hết giờ.');
