INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('e2040000-0000-4000-8000-000000000037', 'e2030000-0000-4000-8000-000000000013', 1, 'TEXT', 'Biểu đồ cột cần ba việc: nêu chủ đề ("The chart shows..."), nói giá trị cao nhất và thấp nhất ("Cycling was the most popular, while walking was the least popular") và so sánh hai mục ("Twice as many people cycled as walked"). Dùng so sánh hơn và nhất đã học. Không liệt kê mọi số liệu, chỉ chọn điểm nổi bật.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('e2040000-0000-4000-8000-000000000037', (SELECT id FROM knowledge_points WHERE code = 'W50_SIMPLE_CHART'));
