INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('e2070000-0000-4000-8000-000000000097', 'e2060000-0000-4000-8000-000000000097', 1, 'A bar chart shows how students travel: bus 40%, bike 30%, walking 20%, car 10%. Which sentence names the highest value?', '[{"optionKey": "A", "content": "The bus was the most popular way to travel.", "sortOrder": 1}, {"optionKey": "B", "content": "The car was the most popular way to travel.", "sortOrder": 2}, {"optionKey": "C", "content": "Walking was the most popular way to travel.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A"}', 1, 'Bus has the highest percentage, 40%.', 'EASY', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('e2070000-0000-4000-8000-000000000097', (SELECT id FROM knowledge_points WHERE code = 'W50_SIMPLE_CHART'), 1.0);
