INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('e2070000-0000-4000-8000-000000000101', 'e2060000-0000-4000-8000-000000000101', 1, 'Which sentence compares two items?', '[{"optionKey": "A", "content": "Wednesday had two more hours of sleep than Monday.", "sortOrder": 1}, {"optionKey": "B", "content": "Sleep is important.", "sortOrder": 2}, {"optionKey": "C", "content": "Tuesday was a day.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A"}', 1, '8 minus 6 is two more hours.', 'MEDIUM', 'PUBLISHED');
