INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('e2040000-0000-4000-8000-000000000039', 'e2030000-0000-4000-8000-000000000014', 1, 'TEXT', 'Email cho bạn có chào ("Hi Linh,"), lý do viết ("I''m writing to ask if you''d like to..."), thông tin cần thiết (khi nào, ở đâu) và kết thân thiện ("Let me know! Best wishes, Hoa"). Dùng dạng rút gọn (I''m, don''t) được, nhưng câu vẫn đúng ngữ pháp và đủ ý. Nêu rõ giờ và nơi để người đọc trả lời được ngay.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('e2040000-0000-4000-8000-000000000039', (SELECT id FROM knowledge_points WHERE code = 'W50_EMAIL'));
