INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('e2070000-0000-4000-8000-000000000103', 'e2060000-0000-4000-8000-000000000103', 1, 'Which opening fits an email to a friend?', '[{"optionKey": "A", "content": "Hi Linh,", "sortOrder": 1}, {"optionKey": "B", "content": "Dear Sir or Madam,", "sortOrder": 2}, {"optionKey": "C", "content": "To whom it may concern,", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A"}', 1, 'Hi plus a name is friendly.', 'EASY', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('e2070000-0000-4000-8000-000000000103', (SELECT id FROM knowledge_points WHERE code = 'W50_EMAIL'), 1.0);
