INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, difficulty, status) VALUES ('e2070000-0000-4000-8000-000000000105', 'e2060000-0000-4000-8000-000000000105', 1, 'Which ending is suitable?', '[{"optionKey": "A", "content": "Let me know if you can come! Best wishes, Hoa", "sortOrder": 1}, {"optionKey": "B", "content": "Yours faithfully, Hoa", "sortOrder": 2}, {"optionKey": "C", "content": "I look forward to your reply at your earliest convenience.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A"}', 1, 'A friendly, short ending fits a friend.', 'EASY', 'PUBLISHED');
